-- 4. Retag existing Christmas photos so the live card ids find them (card id was not in christmas_keys)
update wf_inventory set signals = jsonb_set(signals,'{christmas_photo_gallery}',(select jsonb_agg(case when e->'christmas_keys' ? 'seaworld-orlando-christmas-celebration-2026' and not e->'christmas_keys' ? 'seaworld-orlando-christmas-2026' then jsonb_set(e,'{christmas_keys}',(e->'christmas_keys')||'["seaworld-orlando-christmas-2026"]'::jsonb) else e end order by o) from jsonb_array_elements(signals->'christmas_photo_gallery') with ordinality t(e,o))) where place_id='ChIJfyPWjCh-54gR1SvWozmef5k' and jsonb_typeof(signals->'christmas_photo_gallery')='array';
update wf_inventory set signals = jsonb_set(signals,'{christmas_photo_gallery}',(select jsonb_agg(case when e->'christmas_keys' ? 'disney-jollywood-nights-2026' and not e->'christmas_keys' ? 'jollywood-nights-2026' then jsonb_set(e,'{christmas_keys}',(e->'christmas_keys')||'["jollywood-nights-2026"]'::jsonb) else e end order by o) from jsonb_array_elements(signals->'christmas_photo_gallery') with ordinality t(e,o))) where place_id='ChIJRx6CYyd83YgRD_HjNqPO_7s' and jsonb_typeof(signals->'christmas_photo_gallery')='array';
update wf_inventory set signals = jsonb_set(signals,'{christmas_photo_gallery}',(select jsonb_agg(case when e->'christmas_keys' ? 'mickeys-very-merry-christmas-party-2026' and not e->'christmas_keys' ? 'mvmcp-2026' then jsonb_set(e,'{christmas_keys}',(e->'christmas_keys')||'["mvmcp-2026"]'::jsonb) else e end order by o) from jsonb_array_elements(signals->'christmas_photo_gallery') with ordinality t(e,o))) where place_id='ChIJgUulalN-3YgRGoTaWM2LawY' and jsonb_typeof(signals->'christmas_photo_gallery')='array';
update wf_inventory set signals = jsonb_set(signals,'{christmas_photo_gallery}',(select jsonb_agg(case when e->'christmas_keys' ? 'dazzling-nights-leu-gardens-2026' and not e->'christmas_keys' ? 'dazzling-nights-leu-2026' then jsonb_set(e,'{christmas_keys}',(e->'christmas_keys')||'["dazzling-nights-leu-2026"]'::jsonb) else e end order by o) from jsonb_array_elements(signals->'christmas_photo_gallery') with ordinality t(e,o))) where place_id='ChIJCRCYGrx654gR3G9qoVbWlpY' and jsonb_typeof(signals->'christmas_photo_gallery')='array';

-- 5. Universal card points at Universal Studios Florida; copy the 7 tagged holiday photos from the Universal Orlando Resort row (same urls, no new files)
update wf_inventory u set signals = jsonb_set(coalesce(u.signals,'{}'::jsonb),'{christmas_photo_gallery}',(select r.signals->'christmas_photo_gallery' from wf_inventory r where r.place_id='ChIJvRBCrN9-54gRGZuuaCLGrQE')) where u.place_id='ChIJdd8VlMN-54gRoaU0d_zYhfk' and jsonb_array_length(coalesce(u.signals->'christmas_photo_gallery','[]'::jsonb))=0;

